import React, { useState } from 'react';

const SendMoneyForm = () => {
  const [formData, setFormData] = useState({
    recipient: '',
    amount: '',
    currency: 'USD',
  });
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      // Add your API call logic here
      // For example, you can call a function like sendMoney(formData)
      console.log('Submitting data:', formData);
      setLoading(false);
      alert('Transaction Successful!');
    } catch (error) {
      setLoading(false);
      alert('Transaction failed, please try again');
    }
  };

  return (
    <div className="send-money-form">
      <h2>Send Money</h2>
      <form onSubmit={handleSubmit}>
        {/* Step 1: Recipient details */}
        {step === 1 && (
          <div className="form-step">
            <input
              type="text"
              placeholder="Recipient's Name"
              value={formData.recipient}
              onChange={(e) => setFormData({...formData, recipient: e.target.value})}
              required
            />
            <button type="button" onClick={() => setStep(2)} disabled={!formData.recipient}>Next</button>
          </div>
        )}

        {/* Step 2: Amount and Currency */}
        {step === 2 && (
          <div className="form-step">
            <input
              type="number"
              placeholder="Amount"
              value={formData.amount}
              onChange={(e) => setFormData({...formData, amount: e.target.value})}
              required
            />
            <select
              value={formData.currency}
              onChange={(e) => setFormData({...formData, currency: e.target.value})}
            >
              <option value="USD">USD</option>
              <option value="EUR">EUR</option>
              <option value="GBP">GBP</option>
            </select>
            <button type="button" onClick={() => setStep(3)} disabled={!formData.amount}>Next</button>
            <button type="button" onClick={() => setStep(1)}>Back</button>
          </div>
        )}

        {/* Step 3: Confirmation */}
        {step === 3 && (
          <div className="form-step">
            <h3>Confirm Transaction</h3>
            <p><strong>Recipient:</strong> {formData.recipient}</p>
            <p><strong>Amount:</strong> {formData.amount} {formData.currency}</p>
            <button type="submit" disabled={loading}>
              {loading ? 'Processing...' : 'Submit Transaction'}
            </button>
            <button type="button" onClick={() => setStep(2)}>Back</button>
          </div>
        )}
      </form>
    </div>
  );
};

export default SendMoneyForm;
